-- =============================================================================
-- MIGRACIÓN ETL DETERMINISTA DESDE EXCEL: Ingresos, Gastos Disc., Hipotecario
-- Esquema destino: finanzas (Supabase PostgreSQL)
-- =============================================================================
BEGIN;

DO $$
DECLARE
  v_uid uuid;
BEGIN
  -- Si ya existe un usuario en auth.users (ej. cuenta de Gonzalo), le vincula los datos
  SELECT id INTO v_uid FROM auth.users ORDER BY created_at ASC LIMIT 1;

  -- 1. Cuentas / Medios de Pago

  -- 2. Categorías Estructurales

  -- 3. Préstamo Hipotecario UVA (240 Cuotas)
  ON CONFLICT (id) DO UPDATE SET valor_uva = EXCLUDED.valor_uva, cuota_total_ars = EXCLUDED.cuota_total_ars, cotizacion_mep = EXCLUDED.cotizacion_mep, cuota_usd = EXCLUDED.cuota_usd, deuda_ars = EXCLUDED.deuda_ars, deuda_usd = EXCLUDED.deuda_usd, pagada = EXCLUDED.pagada;

  -- 4. Transacciones Históricas de Ingresos (276 registros) y Gastos Disc. (3640 registros)
  ALTER TABLE finanzas.transacciones DISABLE TRIGGER after_transaccion_saldo;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ON CONFLICT (id) DO UPDATE SET monto = EXCLUDED.monto, monto_caja = EXCLUDED.monto_caja, metadatos = EXCLUDED.metadatos;
  ALTER TABLE finanzas.transacciones ENABLE TRIGGER after_transaccion_saldo;

  -- 5. Grupo Splitwise: Nueva York 2026

  -- 6. Recalcular saldos de todas las cuentas
  PERFORM finanzas.fn_recalcular_saldo_cuenta('38d612b6-760f-5bba-a3e4-689af5f2bc52');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('ab2a2d61-8eff-5a1f-9d9b-0bebaa9f97a7');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('b2351ceb-4a3c-5824-a7c1-89fb1a5370a6');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('d810efe9-dcb0-54e2-ba6e-2cf6ea2ce799');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('efc5482b-9636-5f54-8ef9-7237e92eed33');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('c0d8e8d4-3e4c-5f54-9f7c-adb4cfc64cb8');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('c60339ae-31ad-5b09-a0d6-3678e13c1c6f');
  PERFORM finanzas.fn_recalcular_saldo_cuenta('dfa249f3-6fde-5306-86f4-6159234eb2f7');
END $$;
COMMIT;